        return new Source("{% extends 'base_public.html.twig' %}

{% block title %}Soumettre une Réclamation{% endblock %}

{% block body %}
<div class=\"container py-4\">
    <div class=\"row justify-content-center\">
        <div class=\"col-md-8\">
            <div class=\"card\">
                <div class=\"card-header bg-primary text-white\">
                    <h1 class=\"h4 mb-0\">Soumettre une Réclamation</h1>
                </div>
                <div class=\"card-body\">
                    {{ form_start(form, {'attr': {'class': 'needs-validation'}}) }}
                    
                    <div class=\"mb-3\">
                        {{ form_label(form.category) }}
                        {{ form_widget(form.category) }}
                        {{ form_errors(form.category) }}
                    </div>

                    <div class=\"mb-3\">
                        {{ form_label(form.nom, 'Votre nom') }}
                        {{ form_widget(form.nom, {'attr': {'class': 'form-control'}}) }}
                        {{ form_errors(form.nom) }}
                    </div>

                    <div class=\"mb-3\">
                        {{ form_label(form.email, 'Votre email') }}
                        {{ form_widget(form.email, {'attr': {'class': 'form-control'}}) }}
                        {{ form_errors(form.email) }}
                    </div>

                    <div class=\"mb-3\">
                        {{ form_label(form.message, 'Votre message') }}
                        {{ form_widget(form.message, {'attr': {'class': 'form-control', 'rows': 5}}) }}
                        {{ form_errors(form.message) }}
                    </div>

                    <button type=\"submit\" class=\"btn btn-primary\">Envoyer la réclamation</button>
                    {{ form_end(form) }}
                </div>
            </div>
        </div>
    </div>
</div>
{% endblock %}
